def _rbr_git(*args, **kw):
    """Run git at the repository root. Returns None if git itself is unusable.

    `tag` only labels the diagnostics, so a later round reusing this mechanism reports under its
    own guard name rather than this one's."""
    import subprocess
    try:
        return subprocess.run(('git',) + args, cwd=kw.get('cwd') or os.path.dirname(VERIFICATION),
                              capture_output=True, timeout=kw.get('timeout', 60))
    except Exception as exc:
        print('    %s ancestry: git unusable (%s)'
              % (kw.get('tag', 'R7-RBR'), type(exc).__name__))
        return None


def _rbr_ensure_present(rev, pr_number=None, tag='R7-RBR', cwd=None):
    """Make `rev` available in this clone, or report that it could not be.

    A shallow checkout does not contain the pinned base -- nor, sometimes, the real PR head -- so
    `merge-base` cannot decide the question there. The guard therefore RECOVERS the history itself
    rather than depending on how the repository happened to be cloned: deepening a shallow clone,
    or fetching the commit when it is merely absent, with `refs/pull/<n>/head` as a second attempt
    when a PR number is known and the bare SHA is refused (a fork head). The operations are
    additive: they add objects and change no ref, no worktree file and no branch.

    **This never substitutes for the ancestry check.** It only makes the check answerable; the
    pinned `merge-base --is-ancestor` still runs afterwards and still decides. If recovery fails,
    the guard FAILS."""
    present = _rbr_git('cat-file', '-e', rev + '^{commit}', tag=tag, cwd=cwd)
    if present is None:
        return False
    if present.returncode == 0:
        return True
    shallow = _rbr_git('rev-parse', '--is-shallow-repository', tag=tag, cwd=cwd)
    if shallow is None:
        return False
    if shallow.stdout.decode('utf-8', 'replace').strip() == 'true':
        print('    %s ancestry: shallow checkout; deepening to reach %s' % (tag, rev[:12]))
        got = _rbr_git('fetch', '--unshallow', 'origin', timeout=900, tag=tag, cwd=cwd)
        if got is None or got.returncode != 0:
            got = _rbr_git('fetch', '--deepen=2147483647', 'origin', timeout=900, tag=tag, cwd=cwd)
    else:
        print('    %s ancestry: %s absent; fetching it' % (tag, rev[:12]))
        got = _rbr_git('fetch', 'origin', rev, timeout=900, tag=tag, cwd=cwd)
    if (got is None or got.returncode != 0) and pr_number is not None:
        got = _rbr_git('fetch', 'origin', 'refs/pull/%s/head' % pr_number, timeout=900, tag=tag, cwd=cwd)
    if got is None or got.returncode != 0:
        print('    %s ancestry: recovery of %s FAILED; the check fails rather than skips'
              % (tag, rev[:12]))
        return False
    present = _rbr_git('cat-file', '-e', rev + '^{commit}', tag=tag, cwd=cwd)
    return present is not None and present.returncode == 0


def _rbr_target_commit(env=None, tag='R7-RBR'):
    """The commit the ancestry claim is ABOUT -- and in PR CI that is NOT `HEAD`.

    `actions/checkout` on a `pull_request` event checks out GitHub's **synthetic merge commit**
    `refs/pull/<n>/merge`, which has the PR BASE as a parent by construction. So an ancestry check
    against that `HEAD` passes whatever the PR head does: the base branch already contains the
    pinned commit, and the check would be VACUOUS exactly where it matters most.

    In a PR run the target is therefore the real `pull_request.head.sha`, read from the Actions
    event payload. Outside PR CI, ordinary `HEAD` is the right object and is used.

    Returns `(rev, label, pr_number)`, or `(None, None, None)` to FAIL CLOSED. **There is no
    fallback to the synthetic merge `HEAD`**: an unresolvable PR head fails the guard rather than
    being answered against the wrong object."""
    env = os.environ if env is None else env
    if not env.get('GITHUB_EVENT_NAME', '').startswith('pull_request'):
        return 'HEAD', 'HEAD', None
    path = env.get('GITHUB_EVENT_PATH', '')
    if not path or not os.path.exists(path):
        print('    %s ancestry: pull_request run with no readable event payload; '
              'failing closed rather than certifying the synthetic merge HEAD' % tag)
        return None, None, None
    try:
        with open(path, encoding='utf-8') as fh:
            payload = json.load(fh)
        sha = payload['pull_request']['head']['sha']
        num = payload['pull_request']['number']
    except Exception as exc:
        print('    %s ancestry: cannot resolve pull_request.head.sha (%s); failing closed'
              % (tag, type(exc).__name__))
        return None, None, None
    if not (isinstance(sha, str) and re.fullmatch(r'[0-9a-f]{40}', sha)):
        print('    %s ancestry: pull_request.head.sha is not a full 40-hex SHA; failing closed'
              % tag)
        return None, None, None
    return sha, 'pull_request.head.sha %s' % sha[:12], num


def _rbr_strong_ancestry(base, target, label, num, tag='R7-RBR', cwd=None):
    """The strengthened predicate, factored: `base` an ancestor of `target`, and every commit of
    `git rev-list target ^base` itself a descendant of `base`, recovery included, fail-closed."""
    if not _rbr_ensure_present(base, tag=tag, cwd=cwd):
        return False
    if not _rbr_ensure_present(target, pr_number=num, tag=tag, cwd=cwd):
        return False
    r = _rbr_git('merge-base', '--is-ancestor', base, target, tag=tag, cwd=cwd)
    if r is None:
        return False
    if r.returncode != 0:
        print('    %s ancestry: %s is present but is NOT an ancestor of %s' % (tag, base[:12], label))
        return False
    listed = _rbr_git('rev-list', '%s' % target, '^%s' % base, tag=tag, cwd=cwd)
    if listed is None or listed.returncode != 0:
        print('    %s ancestry: could not enumerate the execution-only history; failing closed' % tag)
        return False
    revs = listed.stdout.decode('utf-8', 'replace').split()
    for rev in revs:
        if not _rbr_ensure_present(rev, pr_number=num, tag=tag, cwd=cwd):
            return False
        step = _rbr_git('merge-base', '--is-ancestor', base, rev, tag=tag, cwd=cwd)
        if step is None:
            return False
        if step.returncode != 0:
            print('    %s ancestry: %s is reachable from %s but does NOT descend from %s -- '
                  'pre-freeze side history' % (tag, rev[:12], label, base[:12]))
            return False
    print('    %s ancestry: certified %s and all %d commit(s) of the execution-only history '
          'descend from %s' % (tag, label, len(revs), base[:12]))
    return True


def _rbr_base_branch_tip(ref, tag='R7-RBR', cwd=None):
    """The CURRENT tip of the pull request's base BRANCH, as `refs/remotes/origin/<ref>` and as
    nothing else.

    `pull_request.base.sha` is NOT a reliable source of it. #644 is the demonstration: that pull
    request's payload still carried base `b78eac870ba3` after the base branch had advanced through
    three later landings to `b7cdf49b9262`, with the head pushed to in between. Whatever the
    field's exact update rule, a value that can sit that far behind cannot answer a question about
    what is on the base branch NOW, and on a branch cut from a historical base it is as old as the
    head, so head-or-`base.sha` adds nothing to head alone. That is why the head-or-`base.sha`
    rule left the false negative it was written to remove exactly where it was.

    The base branch's tip is what the invariant is actually about: an archived landing must still
    be on the branch the pull request proposes to land on. The name comes from the event --
    `pull_request.base.ref`, or `GITHUB_BASE_REF` -- and is resolved ONLY against the
    remote-tracking ref.

    **A local `refs/heads/<ref>` is not accepted in its place**, even when one exists. It is not
    evidence of the remote branch's tip: in a checkout where the remote-tracking ref is absent, a
    local branch of the same name is whatever some earlier operation left there, and substituting
    it would let an abnormal checkout pass a check that should have failed closed. CI fetches
    `+refs/heads/*:refs/remotes/origin/*` under `fetch-depth: 0`, so the ref is there; a missing
    one means the checkout is wrong and is reported as such. If the local ref exists it is named
    in the failure, so the diagnosis is immediate, but it does not gate.

    Resolving a ref is a read of the checkout, and the comment on `_rbr_target_commit` above is
    emphatic that the checkout must not answer this family of questions. The hazard there is
    specific and does not arise here: the synthetic merge `HEAD` of a `pull_request` run has the
    base as a parent AND the head as a parent, so it contains everything either side contains and
    makes the check vacuous. `refs/remotes/origin/<ref>` contains only what the base branch
    contains. It cannot make a landing that sits on the head side alone pass, and for an archived
    landing, being on the base branch is the substantive fact the leg exists to confirm.

    Returns `(sha, label)`, or `(None, reason)` when the name is missing, malformed, or the
    remote-tracking ref does not resolve -- and the caller FAILS CLOSED on that. There is no
    fallback to `base.sha` either: a base branch that no longer carries the landing is the
    rewritten-or-vanished condition, and a stale snapshot that still carries it would hide exactly
    that."""
    if not isinstance(ref, str) or not ref:
        return None, 'the base branch name is absent from the event'
    if ref.startswith('-') or not re.fullmatch(r'[0-9A-Za-z._][0-9A-Za-z._/-]*', ref):
        return None, 'the base branch name %r is not a plain ref name' % ref
    remote = 'refs/remotes/origin/%s' % ref
    r = _rbr_git('rev-parse', '--verify', '--quiet', remote + '^{commit}', tag=tag, cwd=cwd)
    if r is None:
        return None, 'git could not be run to resolve %s' % remote
    if r.returncode == 0:
        sha = r.stdout.decode('utf-8', 'replace').strip()
        if re.fullmatch(r'[0-9a-f]{40}', sha):
            return sha, '%s %s' % (remote, sha[:12])
        return None, '%s did not resolve to a full 40-hex commit' % remote
    local = _rbr_git('rev-parse', '--verify', '--quiet', 'refs/heads/%s^{commit}' % ref,
                     tag=tag, cwd=cwd)
    extra = ''
    if local is not None and local.returncode == 0:
        extra = (' -- a local refs/heads/%s exists at %s and is NOT accepted in its place, being '
                 'no evidence of the remote branch tip'
                 % (ref, local.stdout.decode('utf-8', 'replace').strip()[:12]))
    return None, ('%s does not resolve in this checkout (a shallow or single-branch clone will do '
                  'this; fetch-depth: 0 fetches +refs/heads/*:refs/remotes/origin/*)%s'
                  % (remote, extra))


def _rbr_archive_visibility_targets(env=None, tag='R7-RBR', cwd=None):
    """The commits an ARCHIVED landing may be visible from. **Archive mode only.**

    Execution mode asks its question of one object and one only -- the real `pull_request.head.sha`
    -- and `_rbr_target_commit` above is unchanged and still supplies it. This function exists
    because the ARCHIVE question is different, and asking it of the head alone produced a false
    negative that had nothing to do with the round being checked.

    The failure: under `A.37` an execution branches from its own control plane's merge commit and
    from nothing else, so a pull request opened from a historical base cannot reach seals that
    landed on `main` afterwards. Four such branches failed this leg at once, on four rounds none of
    them touched, while every pinned object was reachable from `main`. Nothing had been rewritten
    or had vanished, which is the only condition this leg exists to detect.

    So on a pull request the archived landing may be visible from the real `pull_request.head.sha`
    **or** from the CURRENT TIP OF THE BASE BRANCH: the first covers a fresh `E` -> `L` -> `P`
    branch whose own seal is on the head side and not yet on the base, the second covers a
    historical branch whose base has since taken seals that landed after it. On a push, or any
    non-pull-request event, the single target is `HEAD` as before.

    The base side is the branch tip, resolved as `refs/remotes/origin/<base ref>` and nothing else,
    and it is NOT `pull_request.base.sha`. That field is not a reliable source of the live tip: on
    #644 it still read `b78eac870ba3` after the base branch had advanced through three later
    landings, with the head pushed to in between, so a rule written on it does not deliver the
    invariant it appears to. It is still read, and printed, as a DIAGNOSTIC. **No case admits the
    synthetic merge `HEAD`**, which has both sides as parents and would make the leg vacuous.

    Returns a list of `(rev, label)` candidates, or `None` to FAIL CLOSED."""
    env = os.environ if env is None else env
    if not env.get('GITHUB_EVENT_NAME', '').startswith('pull_request'):
        return [('HEAD', 'HEAD')]
    path = env.get('GITHUB_EVENT_PATH', '')
    if not path or not os.path.exists(path):
        print('    %s archive: pull_request run with no readable event payload; failing closed '
              'rather than certifying the synthetic merge HEAD' % tag)
        return None
    try:
        with open(path, encoding='utf-8') as fh:
            payload = json.load(fh)
        pr = payload['pull_request']
        head = pr['head']['sha']
        base_ref = (pr.get('base') or {}).get('ref') or env.get('GITHUB_BASE_REF')
        base_sha = (pr.get('base') or {}).get('sha')
    except Exception as exc:
        print('    %s archive: cannot read the pull_request event payload (%s); failing closed'
              % (tag, type(exc).__name__))
        return None
    if not (isinstance(head, str) and re.fullmatch(r'[0-9a-f]{40}', head)):
        print('    %s archive: pull_request.head.sha is not a full 40-hex SHA; failing closed' % tag)
        return None
    tip, why = _rbr_base_branch_tip(base_ref, tag=tag, cwd=cwd)
    if tip is None:
        print('    %s archive: the base branch tip could not be resolved -- %s. '
              'pull_request.base.sha is no reliable source of the live tip and is not accepted in '
              'its place; failing closed' % (tag, why))
        return None
    if isinstance(base_sha, str) and re.fullmatch(r'[0-9a-f]{40}', base_sha):
        print('    %s archive: base branch %s is at %s; the event payload records '
              'pull_request.base.sha %s, which does not gate'
              % (tag, base_ref, tip[:12], base_sha[:12]))
    return [(head, 'pull_request.head.sha %s' % head[:12]), (tip, why)]


def _rbr_archive_ancestry(base, sealed, merge, tag='R7-RBR', env=None, target=None, cwd=None):
    """ARCHIVE MODE -- the same strong certificate, re-run against the SEALED execution head.

    Once an execution PR has merged, neither `HEAD` on `main` nor the head of a later pull request
    is the execution head: both reach every sibling round merged before or after, and a sibling
    branched before this round's freeze is exactly the "pre-freeze side history" the strengthened
    predicate exists to refuse -- correctly for the execution head, wrongly for anything that
    merely contains it. The predicate is a property of the object that was reviewed, so after the
    merge it is re-run against that object: the sealed head pinned by SHA, together with the merge
    commit that carried it.

    Three things are required, each fail-closed, and the FIRST TWO ARE UNCHANGED:

      1. the pinned merge commit's second parent IS the sealed head -- the pin is consistent with
         the record, and this is what makes `E` carried by `L` an intrinsic fact rather than a
         second thing to go looking for;
      2. the sealed head passes the strong check against the base exactly as it did in its own PR
         run -- `base` an ancestor of `sealed`, and every commit of the execution-only history
         itself descending from `base`;
      3. the PINNED MERGE is still visible from the CI target, so that a rewritten or vanished
         history fails rather than passes.

    **Only (3) changed, and only in which targets count.** It asks after the pinned merge alone,
    because (1) has already established that the sealed head is carried by it: `E` is contained in
    `L` by the shape of the object, so a second independent reachability test on `E` would be a
    second escape hatch rather than a second check. The sealed head's own reachability is still
    computed and printed, as DIAGNOSTICS, and does not gate the result. On a pull request the
    candidates are the real head SHA and the CURRENT TIP of the base branch, per
    `_rbr_archive_visibility_targets`; on a push, `HEAD`. Nothing about the base, the
    preregistration pin, or execution mode changes."""
    if target is None:
        cands = _rbr_archive_visibility_targets(env=env, tag=tag, cwd=cwd)
        if cands is None:
            return False
    else:
        cands = [(target, target[:12])]
    for rev in (base, sealed, merge):
        if not _rbr_ensure_present(rev, tag=tag, cwd=cwd):
            return False
    for rev, _lab in cands:
        if not _rbr_ensure_present(rev, tag=tag, cwd=cwd):
            return False
    parents = _rbr_git('log', '-1', '--format=%P', merge, tag=tag, cwd=cwd)
    if parents is None or parents.returncode != 0:
        return False
    ps = parents.stdout.decode('utf-8', 'replace').split()
    if len(ps) < 2 or ps[1] != sealed:
        print('    %s archive: pinned merge %s does not carry the sealed head %s as its second '
              'parent; failing closed' % (tag, merge[:12], sealed[:12]))
        return False
    if not _rbr_strong_ancestry(base, sealed, 'sealed execution head %s' % sealed[:12], None,
                                tag=tag, cwd=cwd):
        return False
    seen = None
    for rev, lab in cands:
        reach = _rbr_git('merge-base', '--is-ancestor', merge, rev, tag=tag, cwd=cwd)
        if reach is None:
            return False
        if reach.returncode == 0:
            seen = lab
            break
    if seen is None:
        print('    %s archive: pinned merge %s is NOT reachable from %s; failing closed'
              % (tag, merge[:12], ' or '.join(lab for _r, lab in cands)))
        return False
    sealed_vis = _rbr_git('merge-base', '--is-ancestor', sealed, cands[0][0], tag=tag, cwd=cwd)
    sealed_note = 'reachable' if (sealed_vis is not None and sealed_vis.returncode == 0) \
        else 'not directly reachable, and carried by the pinned merge'
    print('    %s archive: re-certified sealed head %s (merge %s); pinned merge reachable from %s; '
          'sealed head %s from %s'
          % (tag, sealed[:12], merge[:12], seen, sealed_note, cands[0][1]))
    return True


# ---- R7-SI2: the mandated execution base of seal infrastructure round SI-2, the bootstrap cutover.
# The merge commit of Amendment 2 (#672), certified by push run 35351379664, and NOT the
# preregistration merge da9d69d6 or the Amendment 1 merge 9ca82958, both superseded for
# execution-base purposes by the amendments. NON-SEALING, E -> L, no pin: there is no
# _SI2_SEALED_HEAD and no _SI2_MERGE, not as None and not at all. Defined here, ahead of every
# clause that reads it, and excluded by stem from the legacy inventory SI2-6(b) measures.
# The ONE manifest addition SI2-1 authorizes, named here and not inside the generic region below,
# which carries no round stem: the record set fixed at stage 1 is the manifest at the mandated base
# plus exactly this.
_SI2_STAGE1_ADDITIONS = {'SI1': {'round': 'SI1', 'kind': 'base-only',
                                 'base': '99ab6370470ed9d9e4005551581c6c8c18e54bd2'}}

# ---- SI-3 (SI3-1, R3): THE ROUND-DECLARED INTEGRITY BASELINE. U5 no longer reads a per-round base
# constant and a hard-coded authorization: the record set it holds the manifest against is the seals
# tree at the CURRENT round's mandated execution base, read from git, plus the additions the current
# round's preregistration authorizes, BY STEM. An authorized stem's record is validated by content by
# U3; U5 only admits its presence. Declared here, outside both marker-bounded regions, under a name
# that carries no round stem; the generic region reads it and nothing else about the round.
_MANIFEST_BASELINE = {'base': 'e0be0ab6dca7b6661a008a9f5e1f3a29ea736003', 'authorized': ('CGR',)}


# ---- SI-3 (SI3-2, R2): THE PROSPECTIVE DECLARATION. A sealing round with no record yet declares
# its mandated execution base here, by stem, and U3's prospective path classifies it EXECUTION --
# act 10's strengthened check against that base, asked of the real target -- and LANDED-PENDING-PIN
# at its landing merge. The pin commit P REMOVES the entry when it writes the record; a stem that is
# both declared and recorded is a failure. This is how a round carries its base while it runs
# without writing the legacy representation SI-3 retires. Stem-free in its name, outside both regions.
_MANIFEST_PROSPECTIVE = {'CGR': 'e0be0ab6dca7b6661a008a9f5e1f3a29ea736003'}

# A value that is not a commit, not a hash and equal to nothing a record can hold, returned by the
# accessor below where a record or a field is missing: every comparison and every git call made
# with it FAILS, which is the fail-closed behaviour SI-3's negative case 13 requires, and it is not
# a default in the sense that case forbids -- nothing downstream can treat it as an answer.
_SEAL_UNAVAILABLE = '<manifest field unavailable>'


def _seal_field(stem, field):
    """SI-3 (SI3-2, R1): THE MANIFEST ACCESSOR, the one replacement for a legacy seal-constant read
    anywhere in this file. Returns the named field of one round's manifest record, read through
    `_si1_load` and nothing else. On a missing record, a record that fails the schema, or a field
    the record's kind does not carry -- a base-only record's sealed_head, say -- it returns
    `_SEAL_UNAVAILABLE`, which matches nothing and resolves to nothing, so the contract that asked
    fails closed rather than proceeding on a default."""
    recs, errs = _si1_load()
    if stem in errs or stem not in recs:
        return _SEAL_UNAVAILABLE
    good, _kind = _si1_schema(recs[stem], stem)
    if not good or field not in recs[stem]:
        return _SEAL_UNAVAILABLE
    return recs[stem][field]


def _seal_triple(stem):
    """The (base, sealed_head, merge) triple of a sealed round's record, through the accessor."""
    return (_seal_field(stem, 'base'), _seal_field(stem, 'sealed_head'), _seal_field(stem, 'merge'))

# ---- SI-1's record reader and generic validator, RELOCATED VERBATIM by SI-2 (Amendment 2, point 4)
# from the R7-SI1 section so that the prior-round clauses below can call U3 keyed on their manifest
# records. The marker-bounded region differs from the one SI-1 landed by exactly the two-line O2
# derivation hook recorded in `_SI2_HOOK` below, and R7-SI2 measures that.
# Relative to verification/, because the record reader resolves names through `_artifact`.
_SI1SEALSREL = 'seals'
_SI1SEALS = os.path.join(VERIFICATION, 'seals')

_SI1_HEX = re.compile(r'[0-9a-f]{40}')

# ==== SI1-VALIDATOR-BEGIN ====
# Everything between these markers is the GENERIC validator, and SI1-2 checks mechanically that no
# round stem appears anywhere in it. A stem here would be the per-round coupling this round exists
# to remove.

# The discriminated union. Each kind names the fields it REQUIRES and the fields it FORBIDS, and
# forbids means a hard failure rather than a tolerated null: a base-only record carrying
# `sealed_head: null` is rejected, because those rounds are not seals waiting for fields -- they are
# rounds for which no seal exists, and the schema says so structurally.
_SI1_KINDS = {
    'base-only': (('base',), ('sealed_head', 'merge')),
    'sealed': (('base', 'sealed_head', 'merge'), ()),
}
_SI1_STATES = ('EXECUTION', 'LANDED-PENDING-PIN', 'ARCHIVED')
# Not a fourth state. A record with no lifecycle reports this, and no lifecycle value is ever stored.
_SI1_NA = 'not-applicable'


def _si1_schema(rec, stem):
    """O1 -- the record schema, a discriminated union on `kind`.

    Returns `(True, kind)` or `(False, reason)`. Unknown keys are a failure rather than ignored,
    every hash is checked as 40 lowercase hex before it is used, and a forbidden field is a failure
    even when its value is null."""
    if not isinstance(rec, dict):
        return False, 'schema: record is not a JSON object'
    if rec.get('round') != stem:
        return False, 'schema: round field %r does not match the filename %r' % (rec.get('round'), stem)
    kind = rec.get('kind')
    if kind not in _SI1_KINDS:
        return False, 'schema: kind %r is not one of %s' % (kind, sorted(_SI1_KINDS))
    required, forbidden = _SI1_KINDS[kind]
    # FORBIDDEN IS CHECKED BEFORE UNKNOWN, and the order is the point. A forbidden field is also an
    # unknown one for this kind, so an unknown-key check reached first would report
    # `base-only` carrying `sealed_head` as a stray key rather than as what it is -- a seal asserted
    # for a round that has none. The diagnosis is the value of the check, so it is reported first.
    for field in forbidden:
        if field in rec:
            return False, ('schema: kind %r forbids %s, and it is present (value %r) -- a forbidden '
                           'field is a failure even as null' % (kind, field, rec[field]))
    allowed = {'round', 'kind'} | set(required)
    extra = sorted(set(rec) - allowed)
    if extra:
        return False, 'schema: unknown key(s) %s' % ', '.join(extra)
    for field in required:
        if field not in rec:
            return False, 'schema: kind %r requires %s and it is missing' % (kind, field)
        val = rec[field]
        if not (isinstance(val, str) and _SI1_HEX.fullmatch(val)):
            return False, 'schema: %s is not 40 lowercase hex (%r)' % (field, val)
    return True, kind


def _si1_load(root=None, read=None):
    """The LOGICAL manifest, assembled from one record per round.

    Storage is per-record so that two sibling rounds sealing at the same time touch different files;
    the validator reasons over the SET of records and never over file layout as a source of
    semantics. Returns `(records, errors)` where a record that will not parse is an error rather
    than an absence."""
    root = _SI1SEALSREL if root is None else root
    read = _bb_read if read is None else read
    records, errors = {}, {}
    # `read` goes through `_artifact`, which resolves names RELATIVE to verification/, so the
    # directory is listed absolutely and each record is read by its relative name. Passing an
    # absolute path to the reader silently yields a path under verification/ and a missing file.
    absroot = os.path.join(VERIFICATION, *root.split('/'))
    if not os.path.isdir(absroot):
        return records, errors
    for name in sorted(os.listdir(absroot)):
        if not name.endswith('.json'):
            errors[name] = 'schema: not a .json record'
            continue
        stem = name[:-len('.json')]
        try:
            records[stem] = json.loads(read('%s/%s' % (root, name)).decode('utf-8'))
        except Exception as exc:
            errors[stem] = 'schema: unreadable record (%s)' % type(exc).__name__
    return records, errors


def _si1_derive(sealed, target, tag='R7-SI1', cwd=None, first_parent_only=False):
    """The derivation: the landing merges in `target`'s history whose NON-FIRST parent is exactly
    `sealed`.

    Scoped to REACHABLE history and not to the first-parent spine, because the spine is wrong for
    this repository: of the eighteen archived landings, six lie on it and twelve lie one step off
    it, the second shape arising wherever a round's landing merge and its pin entered main through
    one pull request. `first_parent_only` exists so the narrower scope stays measurable as a
    regression rather than becoming reachable by accident.

    Returns the candidate list, or None if git could not answer -- which the caller treats as a
    failure and never as an empty list."""
    args = ['log', '--format=%H %P']
    if first_parent_only:
        args.append('--first-parent')
    r = _rbr_git(*(args + [target]), tag=tag, cwd=cwd)
    if r is None or r.returncode != 0:
        return None
    out = []
    for line in r.stdout.decode('utf-8', 'replace').split('\n'):
        parts = line.split()
        if len(parts) > 2 and sealed in parts[2:]:
            out.append(parts[0])
    return out


def _si1_landing_of_base(base, target, tag='R7-SI1', cwd=None):
    """The merges in `target`'s history that LOOK like a landing of an execution on `base`: a merge
    whose non-first parent passes the strengthened ancestry check against `base`.

    This is how a round with no manifest record is classified without knowing its execution head.
    Returns the candidate list, or None if git could not answer."""
    r = _rbr_git('log', '--format=%H %P', target, tag=tag, cwd=cwd)
    if r is None or r.returncode != 0:
        return None
    out = []
    for line in r.stdout.decode('utf-8', 'replace').split('\n'):
        parts = line.split()
        if len(parts) > 2:
            for parent in parts[2:]:
                if _si1_quiet_ancestry(base, parent, tag=tag, cwd=cwd):
                    out.append(parts[0])
                    break
    return out


def _si1_quiet_ancestry(base, target, tag='R7-SI1', cwd=None):
    """The strengthened predicate without the narration: `base` an ancestor of `target`, and every
    commit of `git rev-list target ^base` itself a descendant of `base`.

    Used where the answer is a classification step rather than a verdict, so that searching a
    history does not print a verdict line per candidate. The gating calls go through
    `_rbr_strong_ancestry`, which is the same predicate and does narrate."""
    for rev in (base, target):
        if not _rbr_ensure_present(rev, tag=tag, cwd=cwd):
            return False
    r = _rbr_git('merge-base', '--is-ancestor', base, target, tag=tag, cwd=cwd)
    if r is None or r.returncode != 0:
        return False
    listed = _rbr_git('rev-list', target, '^%s' % base, tag=tag, cwd=cwd)
    if listed is None or listed.returncode != 0:
        return False
    for rev in listed.stdout.decode('utf-8', 'replace').split():
        step = _rbr_git('merge-base', '--is-ancestor', base, rev, tag=tag, cwd=cwd)
        if step is None or step.returncode != 0:
            return False
    return True


def _si1_reachable(rev, targets, tag='R7-SI1', cwd=None):
    """Whether `rev` is reachable from any of the visibility targets. Fail-closed: an unresolvable
    target is not a reason to pass."""
    for cand, _why in targets:
        if cand is None:
            continue
        if not _rbr_ensure_present(cand, tag=tag, cwd=cwd):
            continue
        r = _rbr_git('merge-base', '--is-ancestor', rev, cand, tag=tag, cwd=cwd)
        if r is not None and r.returncode == 0:
            return True, _why
    return False, None


def _si1_validate(records, prospective=None, env=None, tag='R7-SI1', cwd=None,
                  target=None, label=None, num=None, targets=None, errors=None, derive=None):
    """O2 -- the generic validator.

    Returns, per round, `(lifecycle, ok, reason)`. It returns a verdict for every record and EITHER
    a lifecycle state OR `_SI1_NA`, because NOT EVERY RECORD HAS A LIFECYCLE: the three states are
    the lifecycle of a SEAL-PRODUCING round, not of every manifest record.

    A `base-only` record is a completed historical non-sealing round. Its schema, its pinned base
    and its record integrity are checked, and it is not classified into any of the three states.
    Classifying it `EXECUTION` -- which the natural reading of "no record, or a record with no
    sealed_head" does -- would leave four completed rounds permanently executing and would keep
    applying execution ancestry semantics to them on every future repository state. A round for
    which no seal exists is not a round whose seal has not arrived yet.

    There is no round-specific branch anywhere below, and SI1-2 checks that mechanically."""
    out = {}
    if target is None:
        target, label, num = _rbr_target_commit(env=env, tag=tag)
        if target is None:
            return None
    if targets is None:
        targets = _rbr_archive_visibility_targets(env=env, tag=tag, cwd=cwd)
    if targets is None:
        # The resolver already said why and failed closed. Returning None here keeps that decision
        # instead of iterating over it: the first candidate passed None onward, where only the order
        # of the checks kept it from being indexed.
        return None
    # The target is compared against commit SHAs below, so a symbolic name is resolved once here.
    # `HEAD` is a legitimate target on a push event and an illegitimate one on a pull request; which
    # it is was decided by `_rbr_target_commit` above, and this only turns a name into an object.
    _res = _rbr_git('rev-parse', '--verify', '--quiet', target + '^{commit}', tag=tag, cwd=cwd)
    if _res is None or _res.returncode != 0:
        return None
    tsha = _res.stdout.decode('utf-8', 'replace').strip()
    for stem, reason in sorted((errors or {}).items()):
        out[stem] = (None, False, reason)
    for stem in sorted(records):
        good, info = _si1_schema(records[stem], stem)
        if not good:
            out[stem] = (None, False, info)
            continue
        rec, kind = records[stem], info
        if kind == 'base-only':
            if not _rbr_ensure_present(rec['base'], tag=tag, cwd=cwd):
                out[stem] = (_SI1_NA, False, 'pinned base %s is absent' % rec['base'][:12])
                continue
            seen, why = _si1_reachable(rec['base'], targets, tag=tag, cwd=cwd)
            out[stem] = (_SI1_NA, seen,
                         ('historical non-sealing record; pinned base %s reachable from %s'
                          % (rec['base'][:12], why)) if seen else
                         'pinned base %s is not reachable; failing closed' % rec['base'][:12])
            continue
        base, sealed, pinned = rec['base'], rec['sealed_head'], rec['merge']
        for rev in (sealed, pinned):
            if not _rbr_ensure_present(rev, tag=tag, cwd=cwd):
                out[stem] = ('ARCHIVED', False,
                             'unreachable: %s is absent from this repository' % rev[:12])
                break
        else:
            cands = (_si1_derive(sealed, target, tag=tag, cwd=cwd) if derive is None
                     else derive(sealed))
            if cands is None:
                out[stem] = ('ARCHIVED', False, 'derivation could not be run; failing closed')
                continue
            uniq = sorted(set(cands))
            if not uniq:
                out[stem] = ('ARCHIVED', False,
                             'zero candidates: no merge reachable from %s carries %s as a non-first '
                             'parent' % (label, sealed[:12]))
                continue
            if len(uniq) > 1:
                out[stem] = ('ARCHIVED', False,
                             'multiple candidates: %s' % ', '.join(c[:12] for c in uniq))
                continue
            if uniq[0] != pinned:
                out[stem] = ('ARCHIVED', False,
                             'disagreement: pinned %s, derived %s' % (pinned[:12], uniq[0][:12]))
                continue
            if not _si1_quiet_ancestry(base, sealed, tag=tag, cwd=cwd):
                out[stem] = ('ARCHIVED', False,
                             'the sealed head %s does not pass the strengthened check against %s'
                             % (sealed[:12], base[:12]))
                continue
            ok = True
            for rev in (pinned, sealed):
                seen, _why = _si1_reachable(rev, targets, tag=tag, cwd=cwd)
                if not seen:
                    out[stem] = ('ARCHIVED', False,
                                 '%s is not reachable from any visibility target; failing closed'
                                 % rev[:12])
                    ok = False
                    break
            if ok:
                out[stem] = ('ARCHIVED', True,
                             'pinned == derived %s; second parent is the sealed head; ancestry and '
                             'reachability hold' % pinned[:12])
    for stem, base in sorted((prospective or {}).items()):
        if not _rbr_ensure_present(base, tag=tag, cwd=cwd):
            out[stem] = (None, False, 'pinned base %s is absent' % base[:12])
            continue
        landings = _si1_landing_of_base(base, target, tag=tag, cwd=cwd)
        if landings is None:
            out[stem] = (None, False, 'landing search could not be run; failing closed')
            continue
        if tsha in landings:
            out[stem] = ('LANDED-PENDING-PIN', True,
                         'the resolved target IS the landing merge; permitted, and the seal record '
                         'is still owed')
            continue
        if landings:
            out[stem] = ('LANDED-PENDING-PIN', False,
                         'seal pending: %s descends from the unpinned landing %s'
                         % (label, landings[0][:12]))
            continue
        good = _rbr_strong_ancestry(base, target, label, num, tag=tag, cwd=cwd)
        out[stem] = ('EXECUTION', good,
                     'prospective execution certified against %s' % base[:12] if good else
                     'prospective execution does not descend from %s' % base[:12])
    return out


def _si1_integrity(at_base, now):
    """Manifest integrity over the ENTRY SET as well as entry contents.

    Mutated, removed and added are three DISTINCT conditions, reported separately. With one record
    per round a deletion is as easy as an edit, and a contents-only rule would let one pass
    invisibly. A change to previously certified seal data requires prospective authorization by the
    round that intends it; this round authorizes none, so its only permitted change to the set is
    its own additions."""
    return {
        'mutated': sorted(k for k in set(at_base) & set(now) if at_base[k] != now[k]),
        'removed': sorted(set(at_base) - set(now)),
        'added': sorted(set(now) - set(at_base)),
    }
# ==== SI1-VALIDATOR-END ====

# ==== SI2-AUTHORITY-BEGIN ====
# Seal infrastructure round SI-2, the bootstrap cutover: the objects that TAKE AUTHORITY. Generic
# code -- no round stem appears between these markers, and R7-SI2 checks that exactly as SI-1's
# second target checks the region above. The per-round clauses below reach the validator only through `_si2_authority`,
# keyed on their manifest record. Four definition slots: U1 the union resolver, U2 the union
# derivation, U3 the authoritative validator with its keyed entry point, U4 the census harness. U5,
# the data-driven integrity rule, is SI-1's `_si1_integrity` applied over the record set fixed at
# stage 1 and fires no slot. The synthetic repository and the negative suite are test code.

# The narrow O2 hook Amendment 2 point 4 permits, recorded here so that R7-SI2 can check that the
# relocated region above differs from the one SI-1 landed by EXACTLY these two edits: the default
# route is still the target-only `_si1_derive`, and only U3 passes a derivation in.
_SI2_HOOK = (
    ("                  target=None, label=None, num=None, targets=None, errors=None):",
     "                  target=None, label=None, num=None, targets=None, errors=None, derive=None):"),
    ("            cands = _si1_derive(sealed, target, tag=tag, cwd=cwd)",
     "            cands = (_si1_derive(sealed, target, tag=tag, cwd=cwd) if derive is None\n"
     "                     else derive(sealed))"),
)


def _si2_union_targets(env=None, tag='R7-SI2', cwd=None):
    """U1 -- the union resolver: the ordered visibility targets of the current event, each with the
    reason it was selected, or None when a required target does not resolve.

    On a push the single target is HEAD. On a pull request the targets are the real
    `pull_request.head.sha` AND the live `refs/remotes/origin/<base ref>` -- never
    `pull_request.base.sha`, never a local branch, never the synthetic merge -- and an unresolvable
    base ref FAILS CLOSED. This is `_rbr_archive_visibility_targets`'s semantics stated once: both
    the derivation (U2) and the visibility leg consume this list and nothing else."""
    return _rbr_archive_visibility_targets(env=env, tag=tag, cwd=cwd)


def _si2_derive_union(sealed, targets, tag='R7-SI2', cwd=None):
    """U2 -- the union derivation, the adjudicated rule made executable: the merges whose NON-FIRST
    parent is exactly `sealed`, over the SET UNION of the targets' reachable histories, deduplicated
    by SHA.

    Returns the sorted candidate list, or None when a target is missing or git could not answer --
    which the caller treats as a failure and never as an empty list. Zero candidates, multiple
    candidates and a unique candidate unequal to the pin remain three distinct failures in U3,
    exactly as before; only the set searched is larger. Where the head side and the base side
    expose two DIFFERENT landings for one sealed head, the union yields multiple candidates and
    fails rather than choosing one."""
    if targets is None:
        return None
    seen = set()
    for rev, _lab in targets:
        if rev is None:
            return None
        cands = _si1_derive(sealed, rev, tag=tag, cwd=cwd)
        if cands is None:
            return None
        seen.update(cands)
    return sorted(seen)


def _si2_validate(records, prospective=None, env=None, tag='R7-SI2', cwd=None, target=None,
                  label=None, num=None, targets=None, errors=None):
    """U3 -- the authoritative validator: SI-1's O2 with U2 in place of the target-only derivation.

    Literally that: the same `_si1_validate`, handed U1's targets for its visibility leg and U2 as
    its derivation. Nothing else about O2 changes -- the schema, the three states, base-only held
    out of the machine, the pin-versus-derived comparison and the fail-closed returns are O2's.
    After the cutover this is what the prior-round clauses call, through `_si2_authority` below."""
    if targets is None:
        targets = _si2_union_targets(env=env, tag=tag, cwd=cwd)
    if targets is None:
        return None
    if target is None:
        target, label, num = _rbr_target_commit(env=env, tag=tag)
        if target is None:
            return None
    ulabel = (('the union of %s' % ' and '.join(str(lab) for _r, lab in targets))
              if len(targets) > 1 else str(targets[0][1]))
    return _si1_validate(records, prospective=prospective, env=env, tag=tag, cwd=cwd, target=target,
                         label=ulabel, num=num, targets=targets, errors=errors,
                         derive=lambda sealed: _si2_derive_union(sealed, targets, tag=tag, cwd=cwd))


_SI2_VERDICTS = {}
_SI2_LEDGER = []


def _si2_manifest_verdicts():
    """U3 over the whole manifest for the live event, computed once per process and reused by every
    per-round clause: the clauses are keyed on their records, and the record set is one object."""
    if 'live' not in _SI2_VERDICTS:
        _recs, _errs = _si1_load()
        _SI2_VERDICTS['live'] = _si2_validate(_recs, errors=_errs, prospective=_MANIFEST_PROSPECTIVE)
    return _SI2_VERDICTS['live']


def _si2_authority(stem, tag='R7-SI2', shadow=None):
    """THE CUTOVER ENTRY POINT. A prior-round ancestry or archive clause is now this call, keyed on
    the round's manifest record `<stem>.json`: the verdict is U3's for that record and nothing
    else. The legacy machinery's verdict for the same clause -- `shadow`, the round's original
    check, still reading its legacy constants -- is computed alongside, RECORDED and printed, and
    GATES NOTHING: the return value does not depend on it, and an exception in it is recorded as no
    verdict rather than allowed to take the gate down. A round with no manifest record gets no
    verdict, which is how R7-SI2's own chronology guard is kept OUT of the cutover by design."""
    verdicts = _si2_manifest_verdicts()
    if verdicts is None:
        life, ok, why = None, False, 'U3 failed closed before answering'
    elif stem not in verdicts:
        life, ok, why = None, False, 'no manifest record %s.json; no verdict' % stem
    else:
        life, ok, why = verdicts[stem]
    sh = None
    if shadow is not None:
        try:
            sh = bool(shadow())
        except Exception as exc:  # noqa: BLE001 -- the shadow gates nothing, so it may not fail the gate either
            sh = None
            why = why + ' [shadow raised %s]' % type(exc).__name__
    _SI2_LEDGER.append({'round': stem, 'tag': tag, 'u3_ok': bool(ok), 'u3_lifecycle': life,
                        'u3_reason': why, 'shadow_ok': sh})
    print('    %s authority: U3 keyed on %s.json -> %s (%s; %s); legacy shadow -> %s, gating nothing'
          % (tag, stem, 'PASS' if ok else 'FAIL', life, why,
             {True: 'PASS', False: 'FAIL', None: 'no verdict'}[sh]))
    return bool(ok)


def _si2_manifest_at_stage1():
    """The record set FIXED at a round's start, U5's baseline: the records at the CURRENT round's
    mandated base, read from git and not from the working tree, plus the records that round's
    preregistration authorizes it to add, by stem, as declared outside this region in
    `_MANIFEST_BASELINE`. Returns None if git could not answer, which U5 treats as a failure."""
    base = _MANIFEST_BASELINE['base']
    r = _rbr_git('ls-tree', '--name-only', '%s:verification/seals' % base, tag='R7-SI2')
    if r is None or r.returncode != 0:
        return None
    out = {}
    for name in r.stdout.decode('utf-8', 'replace').split():
        if not name.endswith('.json'):
            continue
        shown = _rbr_git('show', '%s:verification/seals/%s' % (base, name), tag='R7-SI2')
        if shown is None or shown.returncode != 0:
            return None
        try:
            out[name[:-5]] = json.loads(shown.stdout.decode('utf-8'))
        except ValueError:
            return None
    now, _errs = _si1_load()
    for stem in _MANIFEST_BASELINE['authorized']:
        if stem in now:
            out[stem] = now[stem]
    return out


_SI2_INTEGRITY = {}


def _si2_integrity():
    """U5 -- the data-driven integrity rule: SI-1's `_si1_integrity` over the record set fixed at
    stage 1 against the manifest now, reporting mutated, removed and added as three distinct
    conditions. After the cutover this gates; the per-round seal-integrity comparisons keep running
    as a shadow through `_si2_shadow_integrity` and gate nothing. Computed once per process."""
    if 'live' not in _SI2_INTEGRITY:
        at1 = _si2_manifest_at_stage1()
        now, _errs = _si1_load()
        _SI2_INTEGRITY['live'] = None if at1 is None else _si1_integrity(at1, now)
    return _SI2_INTEGRITY['live']


def _si2_integrity_ok():
    """U5's verdict: the record set fixed at stage 1 is present, unmutated, and joined by nothing."""
    d = _si2_integrity()
    return d is not None and not any(d.values())


# ==== SI2-AUTHORITY-END ====
# Test code from here: the synthetic repository and the negative suite are not definition slots and
# sit outside the stem-free region, as SI-1's O4 did.


def _si2_build_repo():
    """SI-1's synthetic repository, extended with the topologies the union rule's cases need:

        Lx(Hh, E2)          a landing of E2 on the HEAD side only, unreachable from origin/main
        Hx(Lx)              a head that reaches Lx and not Lm
        Hs(Maf)             a head that reaches Lm, as origin/main does
        refs/heads/main-local-only = Maf   a LOCAL branch carrying the landing, never accepted
    """
    d, n, g = _si1_build_repo()
    tree = g('write-tree').stdout.strip()

    def ct(msg, *parents):
        args = ['commit-tree', tree, '-m', msg]
        for p in parents:
            args += ['-p', p]
        return g(*args).stdout.strip()

    n['Lx'] = ct('Lx', n['Hh'], n['E2'])
    n['Hx'] = ct('Hx', n['Lx'])
    n['Hs'] = ct('Hs', n['Maf'])
    g('update-ref', 'refs/heads/main-local-only', n['Maf'])
    return d, n, g


def _si2_negatives():
    """The negative suite SI-2's freeze adds (cases 1 to 8, 11, 12 and 13; 9 and 10 are text and
    static controls in R7-SI2), each required to satisfy its NAMED outcome for its named reason."""
    import shutil
    d, n, _g = _si2_build_repo()
    R = []

    def rec(stem, kind, base, sealed=None, merge=None):
        r = {'round': stem, 'kind': kind, 'base': base}
        if sealed is not None:
            r['sealed_head'] = sealed
        if merge is not None:
            r['merge'] = merge
        return r

    def u3(records, env=None, target=None, targets=None, prospective=None):
        got = _si2_validate(records, prospective=prospective, env=env, cwd=d, target=target,
                            targets=targets)
        if got is None:
            return None, False, 'U3 failed closed and returned no verdict'
        stem = sorted(set(records) | set(prospective or {}))[0]
        return got[stem]

    good_rec = rec('Z', 'sealed', n['B'], n['E2'], n['Lm'])
    try:
        # 1 -- the landing on the live base branch and not reachable from the head: PASSES. This is
        # SI-1's control 10 and the adjudication made executable.
        env1 = _si1_pr_env(d, n['Hh'], 'main', n['c0'])
        t1 = _si2_union_targets(env=env1, tag='R7-SI2', cwd=d)
        c1 = _si2_derive_union(n['E2'], t1, tag='R7-SI2', cwd=d)
        life1, ok1, why1 = u3({'Z': good_rec}, env=env1)
        R.append(('1 landing on the live base branch only', bool(ok1) and c1 == [n['Lm']]
                  and t1 is not None and [r for r, _l in t1] == [n['Hh'], n['Maf']],
                  'targets %s; derived %d candidate(s); %s' % (
                      [l for _r, l in (t1 or [])], len(c1 or []), why1)))
        # 2 -- the same, with the base branch rewound off the landing: FAILS.
        env2 = _si1_pr_env(d, n['Hh'], 'no-landing', n['Maf'])
        life2, ok2, why2 = u3({'Z': good_rec}, env=env2)
        R.append(('2 base branch rewound', (not ok2) and 'zero candidates' in why2, why2))
        # 3 -- an unresolvable remote base ref FAILS CLOSED, and pull_request.base.sha is not
        # accepted in its place even when present, well-formed and carrying the landing; nor is
        # the LOCAL branch of that name, which does carry it.
        env3 = _si1_pr_env(d, n['Hh'], 'main-local-only', n['Maf'])
        t3 = _si2_union_targets(env=env3, tag='R7-SI2', cwd=d)
        life3, ok3, why3 = u3({'Z': good_rec}, env=env3)
        R.append(('3 unresolvable base ref, base.sha and local branch refused',
                  t3 is None and (not ok3) and 'no verdict' in why3, why3))
        # 4 -- head and base each carrying a DIFFERENT merge with E as non-first parent: FAILS as
        # multiple candidates, not resolved in favour of either.
        env4 = _si1_pr_env(d, n['Hx'], 'main', n['c0'])
        c4 = _si2_derive_union(n['E2'], _si2_union_targets(env=env4, tag='R7-SI2', cwd=d),
                               tag='R7-SI2', cwd=d)
        life4, ok4, why4 = u3({'Z': good_rec}, env=env4)
        R.append(('4 different landings on head and base', (not ok4) and 'multiple candidates' in why4
                  and sorted(c4 or []) == sorted([n['Lm'], n['Lx']]), why4))
        # 5 -- head and base carrying the SAME landing: PASSES with exactly one candidate after
        # deduplication; a validator that reports two has not deduplicated.
        env5 = _si1_pr_env(d, n['Hs'], 'main', n['c0'])
        c5 = _si2_derive_union(n['E2'], _si2_union_targets(env=env5, tag='R7-SI2', cwd=d),
                               tag='R7-SI2', cwd=d)
        life5, ok5, why5 = u3({'Z': good_rec}, env=env5)
        R.append(('5 same landing on both sides, deduplicated', bool(ok5) and c5 == [n['Lm']],
                  '%d candidate(s) after deduplication; %s' % (len(c5 or []), why5)))
        # 6 -- the synthetic PR merge offered as a target is REFUSED: U1 never returns it, and the
        # verdict under the real event differs from what the synthetic merge would have given.
        env6 = _si1_pr_env(d, n['Hh'], 'no-landing', n['Maf'])
        t6 = _si2_union_targets(env=env6, tag='R7-SI2', cwd=d)
        life6, ok6, why6 = u3({'Z': good_rec}, env=env6)
        _l, ok6w, _w = u3({'Z': good_rec}, target=n['Hm'], targets=[(n['Hm'], 'synthetic merge HEAD')])
        R.append(('6 synthetic merge refused', t6 is not None and n['Hm'] not in [r for r, _ in t6]
                  and (not ok6) and bool(ok6w), 'resolved event FAILS; the synthetic merge would PASS'))
        # 7 -- a record whose merge is rewritten to a merge that genuinely exists in the union:
        # FAILS on pin-versus-derived disagreement, the case that proves derivation alone is not
        # enough.
        life7, ok7, why7 = u3({'Z': rec('Z', 'sealed', n['B'], n['E2'], n['Wr'])},
                              target=n['Wr'], targets=[(n['Wr'], 'target')])
        R.append(('7 pin rewritten to a real merge in the union', (not ok7) and 'disagreement' in why7,
                  why7))
        # 8 -- a record added beyond SI2-1's single authorization: FAILS as an unauthorized addition
        # under U5, reported as `added` alone.
        at1 = {'A': {'kind': 'sealed', 'base': n['B']}, 'SI1': {'kind': 'base-only', 'base': n['B9']}}
        d8 = _si1_integrity(at1, dict(at1, ZZ={'kind': 'base-only', 'base': n['c0']}))
        R.append(('8 record added beyond SI2-1', [k for k, v in d8.items() if v] == ['added'],
                  'reported %s' % (d8,)))
        # 11 -- RETIRED by SI-3 (SI3-1): it asserted that SI-2 has no record, which SI2.json makes
        # false; R7-SI2's chronology is now keyed on that record.
        # 12 -- a twenty-fourth record: FAILS the scoped R7-SI1 integrity contract AND U5.
        recs12 = {stem: {} for stem in _SI1_TRANSCRIBED} | {'SI1': {}, 'ZZ': {}}
        unauthorized12 = sorted(set(recs12) - _SI1_TRANSCRIBED - _SI1_AUTHORIZED_ADDITIONS)
        d12 = _si1_integrity({k: v for k, v in recs12.items() if k != 'ZZ'}, recs12)
        R.append(('12 twenty-fourth record', unauthorized12 == ['ZZ'] and d12['added'] == ['ZZ']
                  and not d12['mutated'] and not d12['removed'],
                  'scoped R7-SI1 reports %s unauthorized; U5 reports %s' % (unauthorized12, d12)))
        # 13 -- RETIRED by SI-3 (SI3-1) with N13 itself, whose containment half refuses the
        # retirement SI-3 performs; SI-3's own suite carries the successor controls.
    finally:
        shutil.rmtree(d, ignore_errors=True)
    return R


def _rbr_archive_regression():
    """Synthetic regression: two sibling execution rounds merged sequentially, both archived
    certifications valid, and the archive check failing closed on a rewritten history.

    Builds a throwaway repository with the topology that made `main` red on 2026-09-13: a common
    root `c0`; freeze A branched from `c0` and merged as base `BA`; freeze B branched from `c0`
    BEFORE A's merge and merged afterwards as base `BB`; execution A from `BA`; execution B from
    `BB`; then A merged, then B. On that `main`, the HEAD-based reading of A's predicate refuses
    freeze B's commit as pre-freeze side history (the bug), while the archive re-certification of
    A's sealed head passes, as does B's; a target that does not reach A's sealed head fails, a pin
    whose merge commit does not carry the sealed head fails, and a sealed head that itself carries
    side history fails."""
    import shutil
    import tempfile
    cwd = tempfile.mkdtemp(prefix='r7-arch-')
    try:
        cfg = ('-c', 'user.name=r7', '-c', 'user.email=r7@example.invalid',
               '-c', 'commit.gpgsign=false')

        def run(*a):
            r = _rbr_git(*(cfg + a), tag='R7-ARCH', cwd=cwd)
            if r is None or r.returncode != 0:
                raise RuntimeError('git %s: %s' % (' '.join(a), (r.stderr if r else b'').decode(
                    'utf-8', 'replace')))
            return r.stdout.decode('utf-8', 'replace').strip()

        def head():
            return run('rev-parse', 'HEAD')

        run('init', '-q', '-b', 'main')
        run('commit', '-q', '--allow-empty', '-m', 'c0')
        c0 = head()
        run('checkout', '-q', '-b', 'freeze-a', c0)
        run('commit', '-q', '--allow-empty', '-m', 'freeze A')
        run('checkout', '-q', '-b', 'freeze-b', c0)
        run('commit', '-q', '--allow-empty', '-m', 'freeze B (branched before A merged)')
        run('checkout', '-q', 'main')
        run('merge', '-q', '--no-ff', '-m', 'merge freeze A', 'freeze-a')
        ba = head()
        run('merge', '-q', '--no-ff', '-m', 'merge freeze B', 'freeze-b')
        bb = head()
        run('checkout', '-q', '-b', 'exec-a', ba)
        run('commit', '-q', '--allow-empty', '-m', 'execution A')
        a1 = head()
        run('checkout', '-q', '-b', 'exec-b', bb)
        run('commit', '-q', '--allow-empty', '-m', 'execution B')
        b1 = head()
        run('checkout', '-q', 'main')
        run('merge', '-q', '--no-ff', '-m', 'merge execution A', 'exec-a')
        ma = head()
        run('merge', '-q', '--no-ff', '-m', 'merge execution B', 'exec-b')
        mb = head()
        ok = True
        # the bug: A's predicate asked of main's HEAD refuses freeze B's commit
        ok &= not _rbr_strong_ancestry(ba, mb, 'synthetic main', None, tag='R7-ARCH', cwd=cwd)
        # both execution heads certified in their own PR runs (execution mode)
        ok &= _rbr_strong_ancestry(ba, a1, 'synthetic exec A head', None, tag='R7-ARCH', cwd=cwd)
        ok &= _rbr_strong_ancestry(bb, b1, 'synthetic exec B head', None, tag='R7-ARCH', cwd=cwd)
        # both archived certifications valid on the merged main
        ok &= _rbr_archive_ancestry(ba, a1, ma, tag='R7-ARCH', target=mb, cwd=cwd)
        ok &= _rbr_archive_ancestry(bb, b1, mb, tag='R7-ARCH', target=mb, cwd=cwd)
        # fail-closed: a target that does not reach the sealed head (history rewritten or vanished)
        ok &= not _rbr_archive_ancestry(ba, a1, ma, tag='R7-ARCH', target=bb, cwd=cwd)
        # fail-closed: a pin whose merge commit does not carry the sealed head
        ok &= not _rbr_archive_ancestry(ba, a1, mb, tag='R7-ARCH', target=mb, cwd=cwd)
        # fail-closed: a sealed head that itself carries pre-freeze side history
        ok &= not _rbr_archive_ancestry(ba, b1, mb, tag='R7-ARCH', target=mb, cwd=cwd)
        return ok
    except Exception as exc:
        print('    R7-ARCH: synthetic repository could not be built (%s); failing closed'
              % type(exc).__name__)
        return False
    finally:
        shutil.rmtree(cwd, ignore_errors=True)


def _rbr_archive_visibility_regression():
    """Synthetic regression for ARCHIVE VISIBILITY: the head-or-base-BRANCH rule, and the seven
    ways it must still fail closed.

    Builds one topology carrying an archived landing `L` on `main`, plus a historical branch cut
    BEFORE `L` landed -- the shape that produced four simultaneous false negatives on four rounds
    none of the failing branches touched.

    **Every pull-request case here supplies a `pull_request.base.sha` that disagrees with the base
    branch's tip**, because that disagreement is the whole subject. A regression whose payloads
    give the two the same value tests nothing about which of them is read, and an earlier version
    of this function had exactly that defect: it wrote `base.sha` equal to the current tip, so it
    certified a rule that could not work against the payloads GitHub actually sends. Cases 1 and 4
    are a pair and pin the field: the branch tip decides, the snapshot never does, in both
    directions.

    The cases, in order:

      1. a STALE HISTORICAL pull request -- head from before `L`, `base.sha` also from before `L`,
         base BRANCH now carrying it -- PASSES. This is the repair, and it is the case a rule
         written on `base.sha` fails.
      2. a FRESH LANDING pull request -- `L` on the head side only, base branch without it --
         PASSES, which is the case the original single-target rule got right and must keep.
      3. `L` on NEITHER the head nor the base branch FAILS, which is the rewritten-or-vanished
         condition this leg exists for and is what the repair must not give away.
      4. a REWOUND base branch FAILS even though `base.sha` still carries `L`: the snapshot is not
         an escape hatch, and a landing that has left the base branch is exactly condition 3.
      5. FOUR ways the base branch fails to resolve, all FAILING CLOSED and none falling back to
         the snapshot: an unresolvable name; a payload with no base name; a base whose
         remote-tracking ref is ABSENT while a LOCAL branch of that name carries `L`; and a base
         whose remote-tracking ref lacks `L` while a local branch of that name carries it. The
         last two are the point of resolving `refs/remotes/origin/<ref>` and nothing else: a local
         ref is whatever some earlier operation left behind, not evidence of the remote tip, and
         accepting it would let an abnormal checkout pass a check that should have failed.
      6. a MALFORMED `E` -> `L` relation FAILS even when `L` is plainly visible; a PUSH whose
         `HEAD` does not carry `L` FAILS, the non-pull-request path being unchanged; and EXECUTION
         mode is untouched and remains real-head-only.

    And the control that runs through all of them: the SYNTHETIC merge `HEAD` of the checkout
    cannot make any case pass. Every failing pull-request case is run with the working tree sitting
    on a commit that DOES carry `L`, so a reading that consulted the checkout's `HEAD` instead of
    the event would pass them. They must still fail."""
    import shutil
    import tempfile
    cwd = tempfile.mkdtemp(prefix='r7-vis-')
    try:
        cfg = ('-c', 'user.name=r7', '-c', 'user.email=r7@example.invalid',
               '-c', 'commit.gpgsign=false')

        def run(*a):
            r = _rbr_git(*(cfg + a), tag='R7-VIS', cwd=cwd)
            if r is None or r.returncode != 0:
                raise RuntimeError('git %s' % ' '.join(a))
            return r.stdout.decode('utf-8', 'replace').strip()

        def head():
            return run('rev-parse', 'HEAD')

        run('init', '-q', '-b', 'main')
        run('commit', '-q', '--allow-empty', '-m', 'c0')
        c0 = head()
        # the historical branch, cut before anything sealed
        run('checkout', '-q', '-b', 'historical', c0)
        run('commit', '-q', '--allow-empty', '-m', 'a historical control plane')
        hist = head()
        # the sealed round: freeze merge B, execution E, landing L
        run('checkout', '-q', 'main')
        run('commit', '-q', '--allow-empty', '-m', 'freeze')
        b = head()
        run('checkout', '-q', '-b', 'execution', b)
        run('commit', '-q', '--allow-empty', '-m', 'execution E')
        e = head()
        run('checkout', '-q', 'main')
        run('merge', '-q', '--no-ff', '-m', 'landing L', 'execution')
        ell = head()
        run('commit', '-q', '--allow-empty', '-m', 'a later sibling')
        main_now = head()
        # Remote-tracking refs, which are the ONLY thing the base side resolves against.
        run('update-ref', 'refs/remotes/origin/main', main_now)
        # a base branch that does NOT carry the landing, for the rewind and head-only cases
        run('branch', 'no-landing', b)
        run('update-ref', 'refs/remotes/origin/no-landing', b)
        # local-only: a local branch carrying the landing with NO remote-tracking ref at all
        run('branch', 'local-only', main_now)
        # diverged: the remote-tracking ref lacks the landing, the local branch of that name has it
        run('branch', 'diverged', main_now)
        run('update-ref', 'refs/remotes/origin/diverged', b)
        run('checkout', '-q', 'main')

        payloads = {}

        def env_for(name, head_sha, base_sha, base_ref='main', omit_ref=False):
            p = os.path.join(cwd, 'event-%s.json' % name)
            base = {'sha': base_sha}
            if not omit_ref:
                base['ref'] = base_ref
            with open(p, 'w', encoding='utf-8') as fh:
                json.dump({'pull_request': {'number': 1,
                                            'head': {'sha': head_sha},
                                            'base': base}}, fh)
            payloads[name] = p
            return {'GITHUB_EVENT_NAME': 'pull_request', 'GITHUB_EVENT_PATH': p}

        ok = True
        # 1. stale historical head AND a stale base.sha, base branch now carries L -> PASSES.
        #    This is the real GitHub shape, and the head-or-base.sha rule fails it.
        ok &= _rbr_archive_ancestry(b, e, ell, tag='R7-VIS', cwd=cwd,
                                    env=env_for('stale', hist, c0, 'main'))
        # 2. fresh landing: L on the head side only, base branch without it -> PASSES
        ok &= _rbr_archive_ancestry(b, e, ell, tag='R7-VIS', cwd=cwd,
                                    env=env_for('fresh', ell, c0, 'no-landing'))
        # 3. L on NEITHER the head nor the base branch -> FAILS. The checkout sits on main, which
        #    DOES carry L, so a reading that consulted the synthetic merge HEAD would pass this.
        ok &= not _rbr_archive_ancestry(b, e, ell, tag='R7-VIS', cwd=cwd,
                                        env=env_for('neither', hist, c0, 'no-landing'))
        # 4. the base branch has been REWOUND off the landing while base.sha still carries it ->
        #    FAILS. The pair (1, 4) is what pins the field: tip decides, snapshot never does.
        ok &= not _rbr_archive_ancestry(b, e, ell, tag='R7-VIS', cwd=cwd,
                                        env=env_for('rewound', hist, main_now, 'no-landing'))
        # 5. four ways the base branch fails to resolve -> all FAIL closed, none falling back to
        #    base.sha, which in every one of them carries the landing.
        ok &= not _rbr_archive_ancestry(b, e, ell, tag='R7-VIS', cwd=cwd,
                                        env=env_for('unknown-ref', hist, main_now, 'no-such-branch'))
        ok &= not _rbr_archive_ancestry(b, e, ell, tag='R7-VIS', cwd=cwd,
                                        env=env_for('no-ref', hist, main_now, omit_ref=True))
        #    local-only: refs/heads/local-only carries L, no refs/remotes/origin/local-only exists.
        #    A local ref is not evidence of the remote branch tip and must not be substituted.
        ok &= not _rbr_archive_ancestry(b, e, ell, tag='R7-VIS', cwd=cwd,
                                        env=env_for('local-only', hist, main_now, 'local-only'))
        #    diverged: the remote-tracking ref lacks L, the local branch of that name carries it.
        #    The remote decides, so this FAILS.
        ok &= not _rbr_archive_ancestry(b, e, ell, tag='R7-VIS', cwd=cwd,
                                        env=env_for('diverged', hist, main_now, 'diverged'))
        # 6a. malformed E -> L: the pinned merge does not carry the sealed head, L plainly visible
        ok &= not _rbr_archive_ancestry(b, hist, ell, tag='R7-VIS', cwd=cwd,
                                        env=env_for('malformed', main_now, main_now, 'main'))
        # 6b. push with HEAD not carrying L -> FAILS; on main -> PASSES
        run('checkout', '-q', 'historical')
        ok &= not _rbr_archive_ancestry(b, e, ell, tag='R7-VIS', cwd=cwd,
                                        env={'GITHUB_EVENT_NAME': 'push'})
        run('checkout', '-q', 'main')
        ok &= _rbr_archive_ancestry(b, e, ell, tag='R7-VIS', cwd=cwd,
                                    env={'GITHUB_EVENT_NAME': 'push'})
        # 6c. EXECUTION mode untouched: the target is the head SHA, never the base
        tgt, _lab, _n = _rbr_target_commit(env=env_for('exec', hist, main_now, 'main'),
                                           tag='R7-VIS')
        ok &= (tgt == hist)
        # and the strengthened predicate still refuses a base-only target
        ok &= not _rbr_strong_ancestry(b, hist, 'synthetic historical head', None,
                                       tag='R7-VIS', cwd=cwd)
        ok &= _rbr_strong_ancestry(b, e, 'synthetic execution head', None, tag='R7-VIS', cwd=cwd)
        return ok
    except Exception as exc:
        print('    R7-VIS: synthetic repository could not be built (%s); failing closed'
              % type(exc).__name__)
        return False
    finally:
        shutil.rmtree(cwd, ignore_errors=True)


ok_vis = _rbr_archive_visibility_regression()
check('R7-VIS', ok_vis,
      'Archive-mode VISIBILITY, synthetic regression for the head-or-base-BRANCH repair. Under A.37 an execution '
      'branches from its own control plane merge and from nothing else, so a pull request opened from a historical '
      'base cannot reach seals that landed afterwards; four branches failed this leg at once on four rounds none of '
      'them touched, while every pinned object was reachable from main. Nothing had been rewritten, which is the '
      'only condition the leg exists to detect. The repair asks after the PINNED MERGE alone -- the sealed head '
      'being carried by it is already established by the second-parent check, so a second reachability test on the '
      'sealed head would be a second escape hatch, not a second check -- and accepts it on the real head SHA of a '
      'pull request or on the CURRENT TIP of its base branch, HEAD on a push. The base side is refs/remotes/origin/'
      '<base ref> and NOTHING else -- not pull_request.base.sha, which is no reliable source of the live tip (#644 '
      'still carried base b78eac870ba3 after the base branch had advanced through three later landings, with its '
      'head pushed to in between), and not a local refs/heads/<base ref>, which is whatever an earlier operation '
      'left behind rather than evidence of the remote branch. base.sha is printed as a diagnostic and does not '
      'gate. Every pull-request case here gives base.sha a value that DISAGREES with the branch tip, because which '
      'of the two is read is the whole subject and a regression whose payloads agree tests nothing: a stale head '
      'with a stale base.sha whose base branch now carries the landing PASSES, and a rewound base branch whose '
      'base.sha still carries it FAILS. Also exercised: a fresh landing on the head side only PASSES; the landing '
      'on neither side FAILS; and four resolution failures all FAIL CLOSED with no fallback to the snapshot -- an '
      'unknown base name, a payload with no base name, a base whose remote-tracking ref is absent while a local '
      'branch of that name carries the landing, and a base whose remote-tracking ref lacks the landing while a '
      'local branch of that name carries it. Further: a malformed sealed-head-to-merge relation FAILS even with '
      'the merge plainly visible; a push whose HEAD does not carry the landing FAILS; and execution mode is '
      'unchanged, its target still the real head SHA and never the base, with the strengthened predicate still '
      'refusing a base-only target. Every failing pull-request case runs with the checkout sitting on a commit that '
      'DOES carry the landing, so a reading that consulted the synthetic merge HEAD instead of the event would pass '
      'them and does not.')


ok_arch = _rbr_archive_regression()
check('R7-ARCH', ok_arch,
      'Provenance-guard archive mode, synthetic regression: two sibling execution rounds whose freezes both branch '
      'from one root, merged in sequence. The HEAD-based reading of the strengthened predicate is checked to REFUSE '
      'the merged main for the first round (the sibling freeze is pre-freeze side history relative to that base -- '
      'the failure main showed after #598, #596 and #597 merged), while both execution heads certify in execution '
      'mode and BOTH archived certifications -- the same strong check re-run against each sealed head, with the '
      'pinned merge commit required to carry it and both required reachable from the target -- remain valid. '
      'Fail-closed is checked three ways: a target that does not reach the sealed head, a pin whose merge commit '
      'does not carry the sealed head, and a sealed head that itself carries side history all FAIL. No blob pin '
      'and no base is touched by archive mode; it re-certifies the object that was reviewed.')


def _rbr_base_ancestry():
    """CUT OVER BY SI-2 (SI2-3): this round's ancestry verdict is U3's, keyed on its manifest record
    RBR.json, and nothing else. The round's original check, once computed alongside as the shadow and
    gating nothing, was retired by SI-3 (SI3-3) with the legacy constants it read."""
    return _si2_authority('RBR', tag='R7-RBR')


def _rbr_outcome(t=None):
    """B3 -- the outcome is RB3 with RB1-A and RB1-B DERIVED from it, not three findings.

    RB3 is the statement about which control does the work; presenting the per-witness labels as
    independent results would overstate what was proved three times over."""
    t = _RBR1 if t is None else t
    return ('## Outcome: **`RB3`**, and from it **`RB1-A`** and **`RB1-B`**' in t
            and '**`R-2` ALONE forces every same-interface readback to agree with the merged '
                '`R_{a\u2080}` on every modulus-squared unitary matrix on the dilated carrier**'
                in t
            and '`R-1` and `R-3` are **redundant for this theorem**' in t)


def _rbr_stop_not_fired(t=None):
    """B4 -- the exact heterogeneous cut IS represented, so the formalization stop did NOT fire.

    Act 9 made an unencodable cut a stop rather than a scope note. The guard requires the round to
    say which way that went, and to say no RB1 label was assigned against a substitute class."""
    t = _RBR1 if t is None else t
    return ('**The stop did not fire.**' in t
            and '`R-3` quantified over a bijection of **two** label sets' in t
            and '**No `RB1` label here is assigned against a substitute class.**' in t)


def _rbr_nonempty_first(t=None):
    """B5 -- nonemptiness is proved BEFORE any universal statement, from the merged theorems.

    A universal over an unexhibited class is not a result, and act 9 made this an obligation."""
    t = _RBR1 if t is None else t
    return ('**Nonemptiness is proved before any universal statement is made**' in t
            and '`readback_isColStochastic` (`R-1`), `readback_of_admissible` (`R-2`), '
                '`readback_relabel` (`R-3`' in t
            and '**The member is constructed inside that proof**, not as a top-level definition.'
                in t)


def _rbr_p0_not_closed(t=None):
    """B6 -- P0 is NOT closed: the map axis only, with the anchor axis left live.

    The single most likely over-reading of RB3, and the reason act 9 split P0a from P0b before
    execution. The round also carries a FORMAL record of the anchorwise shape, so the limit is
    structural rather than promissory."""
